            <div><label className="text-sm font-medium mb-1.5 block">Kondisi Barang</label><select value={kondisi} onChange={(e) => setKondisi(e.target.value)} className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none focus:border-[#2563eb]"><option value="BAIK">Baik (Good)</option><option value="RUSAK">Rusak (Damage)</option></select><p className="text-xs text-[#6b7688] mt-1">Stok rusak dicatat terpisah dari stok baik.</p></div>
          </div>
          <div className="mt-4"><label className="text-sm font-medium mb-1.5 block">Keterangan</label><textarea value={ket} onChange={(e) => setKet(e.target.value)} rows={2} placeholder="Muat pagi — truk B 9021 XX..." className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none focus:border-[#2563eb] resize-none" /></div>
          <button data-testid="txn-submit-btn" onClick={submit} className="btn-primary w-full mt-5 flex items-center justify-center gap-2 py-3 rounded-lg font-semibold text-sm"><Save size={16} /> Simpan Stok {type === 'MASUK' ? 'Masuk' : 'Keluar'}</button>
        </div>

        <div className="card-surface p-6 h-fit">
          <h2 className="font-display text-lg font-bold mb-4">Ringkasan Transaksi</h2>
          <span className="text-xs px-2.5 py-1 rounded-full font-semibold" style={{ background: type === 'MASUK' ? 'rgba(34,197,94,.15)' : 'rgba(239,68,68,.15)', color: type === 'MASUK' ? '#22c55e' : '#ef4444' }}>{type}</span>
          <div className="mt-5 space-y-3 text-sm">
            {[['Jenis barang', chosen.length], ['Total unit', formatNum(totalUnit)], ['Total berat', totalBerat.toFixed(2) + ' kg'], ['Estimasi nilai', formatRp(totalNilai)]].map(([l, v]) => (
              <div key={l} className="flex justify-between items-center border-b border-[#151d28] pb-3"><span className="text-[#8b93a1]">{l}</span><span className="font-mono font-semibold">{v}</span></div>
            ))}
          </div>
          {chosen.length === 0 ? <p className="text-xs text-[#6b7688] mt-4">Pilih barang untuk melihat perkiraan stok setelah transaksi.</p> : (
            <div className="mt-4 space-y-2">{chosen.map((r) => (<div key={r.productId} className="text-xs p-2.5 rounded-lg bg-[#0b0f17] border border-[#151d28]"><div className="font-medium">{r.product.name}</div><div className="text-[#8b93a1] font-mono">{formatNum(r.product.stock)} → {formatNum(type === 'MASUK' ? r.product.stock + Number(r.qty) : r.product.stock - Number(r.qty))} {r.product.unit}</div></div>))}</div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CatatStok;

import React, { useState } from 'react';
import { Upload, Download, Plus, Search, Pencil, Trash2, X } from 'lucide-react';
import { useData } from '../context/DataContext';
import { formatRp, formatNum, catColor, CATEGORIES } from '../mock';
import { toast } from 'sonner';

const empty = { name: '', sku: '', category: 'F&B / Bahan Makanan', stock: 0, damaged: 0, cost: 0, exp: '', location: '', supplier: '', min: 0, unit: 'Pcs', weight: 0, secondary: 'Dus' };

const DaftarProduk = () => {
  const { products, suppliers, addProduct, updateProduct, deleteProduct } = useData();
  const [q, setQ] = useState('');
  const [cat, setCat] = useState('SEMUA');
  const [modal, setModal] = useState(null); // {mode, data}

  const filtered = products.filter((p) => (cat === 'SEMUA' || p.category === cat) && (p.name.toLowerCase().includes(q.toLowerCase()) || p.sku.toLowerCase().includes(q.toLowerCase()))).sort((a, b) => a.name.localeCompare(b.name));

  const save = () => {
    const d = modal.data;
    if (!d.name || !d.sku) { toast.error('Nama & SKU wajib diisi'); return; }
    if (modal.mode === 'add') { addProduct(d); toast.success('Produk ditambahkan'); }
    else { updateProduct(d.id, d); toast.success('Produk diperbarui'); }
    setModal(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <div className="label-mono mb-2">Master Data</div>
          <h1 className="font-display text-4xl font-bold">Daftar Produk</h1>
          <p className="text-[#8b93a1] mt-2">{filtered.length} dari {products.length} produk ditampilkan</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => toast.info('Fitur import tersedia di halaman Import Data')} className="inline-flex items-center gap-2 text-sm font-medium px-4 py-2.5 rounded-lg border border-[#242f3d] hover:bg-[#141a24] transition-colors"><Upload size={15} /> Import Data</button>
          <button onClick={() => toast.success('Excel diunduh (mock)')} className="inline-flex items-center gap-2 text-sm font-medium px-4 py-2.5 rounded-lg border border-[#242f3d] hover:bg-[#141a24] transition-colors"><Download size={15} /> Unduh Excel</button>
          <button data-testid="add-product-btn" onClick={() => setModal({ mode: 'add', data: { ...empty } })} className="btn-primary inline-flex items-center gap-2 text-sm font-semibold px-4 py-2.5 rounded-lg"><Plus size={15} /> Tambah Produk</button>
        </div>
      </div>

      <div className="card-surface p-6">
        <div className="flex flex-wrap gap-3 mb-5">
          <div className="relative flex-1 min-w-[240px]">
            <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#6b7688]" />
            <input data-testid="product-search-input" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Cari nama produk atau kode SKU..." className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg pl-9 pr-3 py-2.5 text-sm outline-none focus:border-[#2563eb]" />
          </div>
          <select value={cat} onChange={(e) => setCat(e.target.value)} className="bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none focus:border-[#2563eb] min-w-[200px]">
            <option value="SEMUA">SEMUA</option>
            {CATEGORIES.map((c) => <option key={c.name} value={c.name}>{c.name}</option>)}
          </select>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm tbl">
            <thead><tr className="text-left border-b border-[#1a222e]">{['Nama Produk', 'SKU', 'Kategori', 'Stok Baik', 'Stok Rusak', 'Harga Modal', 'Nilai Total', 'Supplier / Lokasi', 'Aksi'].map((h) => <th key={h} className="py-2.5 pr-4 font-semibold whitespace-nowrap">{h}</th>)}</tr></thead>
            <tbody>
              {filtered.length === 0 ? <tr><td colSpan={9} className="py-8 text-center text-[#6b7688]">Tidak ada produk.</td></tr> : filtered.map((p) => (
                <tr key={p.id} className="tbl-row border-b border-[#131a24]">
                  <td className="py-3 pr-4 font-medium">{p.name}</td>
                  <td className="py-3 pr-4 font-mono text-xs text-[#8b93a1]">{p.sku}</td>
                  <td className="py-3 pr-4"><span className="text-xs px-2 py-0.5 rounded-full whitespace-nowrap" style={{ background: `${catColor(p.category)}1f`, color: catColor(p.category) }}>{p.category}</span></td>
                  <td className="py-3 pr-4 font-mono whitespace-nowrap">{formatNum(p.stock)} {p.unit}</td>
                  <td className="py-3 pr-4 font-mono">{p.damaged || 0}</td>
                  <td className="py-3 pr-4 font-mono whitespace-nowrap">{formatRp(p.cost)}</td>
                  <td className="py-3 pr-4 font-mono whitespace-nowrap">{formatRp(p.stock * p.cost)}</td>
                  <td className="py-3 pr-4 text-xs"><div className="text-[#c7d0dc]">{p.supplier}</div><div className="text-[#6b7688]">{p.location}</div></td>
                  <td className="py-3 pr-4"><div className="flex gap-1.5">
                    <button data-testid={`edit-product-btn-${p.sku}`} onClick={() => setModal({ mode: 'edit', data: { ...p } })} className="w-8 h-8 rounded-lg border border-[#242f3d] flex items-center justify-center text-[#8b93a1] hover:text-[#60a5fa] hover:border-[#2563eb] transition-colors"><Pencil size={14} /></button>
                    <button data-testid={`delete-product-btn-${p.sku}`} onClick={() => { if (window.confirm('Hapus produk ini?')) { deleteProduct(p.id); toast.success('Produk dihapus'); } }} className="w-8 h-8 rounded-lg border border-[#242f3d] flex items-center justify-center text-[#8b93a1] hover:text-[#ef4444] hover:border-[#ef4444] transition-colors"><Trash2 size={14} /></button>
                  </div></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {modal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4" onClick={() => setModal(null)}>
          <div className="card-surface w-full max-w-2xl p-6 fade-up" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-5"><h2 className="font-display text-xl font-bold">{modal.mode === 'add' ? 'Tambah Produk' : 'Edit Produk'}</h2><button data-testid="product-modal-close-btn" onClick={() => setModal(null)} className="text-[#8b93a1] hover:text-white"><X size={20} /></button></div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {[['name', 'Nama Produk', 'text'], ['sku', 'SKU', 'text'], ['stock', 'Stok Baik', 'number'], ['damaged', 'Stok Rusak', 'number'], ['cost', 'Harga Modal (Rp)', 'number'], ['min', 'Stok Minimum', 'number'], ['location', 'Lokasi', 'text'], ['weight', 'Berat/Unit (kg)', 'number']].map(([k, l, t]) => (
                <div key={k}><label className="text-xs font-medium mb-1 block text-[#8b93a1]">{l}</label><input data-testid={`product-form-${k}`} type={t} value={modal.data[k]} onChange={(e) => setModal({ ...modal, data: { ...modal.data, [k]: t === 'number' ? Number(e.target.value) : e.target.value } })} className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2 text-sm outline-none focus:border-[#2563eb]" /></div>
              ))}
              <div><label className="text-xs font-medium mb-1 block text-[#8b93a1]">Kategori</label><select value={modal.data.category} onChange={(e) => setModal({ ...modal, data: { ...modal.data, category: e.target.value } })} className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2 text-sm outline-none focus:border-[#2563eb]">{CATEGORIES.map((c) => <option key={c.name}>{c.name}</option>)}</select></div>
              <div><label className="text-xs font-medium mb-1 block text-[#8b93a1]">Supplier</label><select value={modal.data.supplier} onChange={(e) => setModal({ ...modal, data: { ...modal.data, supplier: e.target.value } })} className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2 text-sm outline-none focus:border-[#2563eb]"><option value="">Pilih supplier...</option>{suppliers.map((s) => <option key={s.id}>{s.name}</option>)}</select></div>
              <div><label className="text-xs font-medium mb-1 block text-[#8b93a1]">Satuan</label><input value={modal.data.unit} onChange={(e) => setModal({ ...modal, data: { ...modal.data, unit: e.target.value } })} className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2 text-sm outline-none focus:border-[#2563eb]" /></div>
            </div>
            <div className="flex justify-end gap-2 mt-6"><button onClick={() => setModal(null)} className="px-4 py-2.5 rounded-lg border border-[#242f3d] text-sm hover:bg-[#141a24]">Batal</button><button data-testid="product-save-btn" onClick={save} className="btn-primary px-5 py-2.5 rounded-lg text-sm font-semibold">Simpan</button></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DaftarProduk;

import React, { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, Layers, AlertTriangle, Sparkles, Activity, Upload, Plus, Search, ClipboardList, ArrowUpRight, ArrowDownRight } from 'lucide-react';
import { useData } from '../context/DataContext';
import { formatRp, formatRpShort, formatNum, formatDate, catColor, CATEGORIES } from '../mock';

const StatCard = ({ icon: Icon, label, value, sub, color }) => (
  <div className="card-surface stat-card p-5">
    <div className="w-10 h-10 rounded-xl flex items-center justify-center mb-8" style={{ background: `${color}1f`, color }}><Icon size={20} /></div>
    <div className="label-mono mb-1">{label}</div>
    <div className="font-display text-3xl font-bold">{value}</div>
    <div className="text-xs text-[#6b7688] mt-1">{sub}</div>
  </div>
);

const Dashboard = () => {
  const { products, transactions } = useData();
  const navigate = useNavigate();
  const [q, setQ] = useState('');

  const totalUnits = products.reduce((a, p) => a + p.stock, 0);
  const totalDamaged = products.reduce((a, p) => a + (p.damaged || 0), 0);
  const totalValue = products.reduce((a, p) => a + p.stock * p.cost, 0);
  const activity30 = transactions.reduce((a, t) => a + Math.abs(t.change), 0);
  const lowStock = products.filter((p) => p.stock <= p.min);

  const chart = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) { const d = new Date(); d.setDate(d.getDate() - i); days.push(d); }
    return days.map((d) => {
      const key = `${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
      const vol = transactions.filter((t) => { const td = new Date(t.time); return td.getMonth() === d.getMonth() && td.getDate() === d.getDate(); }).reduce((a, t) => a + Math.abs(t.change), 0);
      return { key, vol };
    });
  }, [transactions]);
  const maxVol = Math.max(...chart.map((c) => c.vol), 1);

  const byCat = CATEGORIES.map((c) => ({ ...c, count: products.filter((p) => p.category === c.name).length, val: products.filter((p) => p.category === c.name).reduce((a, p) => a + p.stock * p.cost, 0) })).filter((c) => c.count > 0);
  const totCat = byCat.reduce((a, c) => a + c.val, 0) || 1;

  const filtered = products.filter((p) => p.name.toLowerCase().includes(q.toLowerCase()) || p.sku.toLowerCase().includes(q.toLowerCase())).sort((a, b) => a.name.localeCompare(b.name));

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <div className="label-mono mb-2">Pusat Kendali Gudang</div>
          <h1 className="font-display text-4xl font-bold">Ringkasan Penyimpanan Stok</h1>
          <p className="text-[#8b93a1] mt-2 max-w-xl">Pantau nilai aset inventori, perputaran barang, dan aktivitas terakhir gudang Anda.</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => navigate('/import')} className="inline-flex items-center gap-2 text-sm font-medium px-4 py-2.5 rounded-lg border border-[#242f3d] hover:bg-[#141a24] transition-colors"><Upload size={15} /> Import Data SKU</button>
          <button onClick={() => navigate('/produk')} className="btn-primary inline-flex items-center gap-2 text-sm font-semibold px-4 py-2.5 rounded-lg"><Plus size={15} /> Tambah Produk</button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard icon={Box} label="Total Ragam Produk" value={formatNum(products.length)} sub="SKU aktif terdaftar" color="#3b82f6" />
        <StatCard icon={Layers} label="Total Unit Fisik Stok" value={formatNum(totalUnits)} sub="Kuantitas seluruh gudang" color="#a855f7" />
        <StatCard icon={AlertTriangle} label="Stok Rusak (Damage)" value={formatNum(totalDamaged)} sub="Unit kondisi rusak" color="#ef4444" />
        <StatCard icon={Sparkles} label="Total Nilai Inventori" value={formatRpShort(totalValue)} sub="Harga modal × jumlah stok" color="#22c55e" />
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard icon={Activity} label="Aktivitas 30 Hari" value={formatNum(activity30)} sub="Unit masuk & keluar" color="#eab308" />
      </div>

      <div className="card-surface p-6">
        <div className="flex items-center gap-3 mb-4">
          <AlertTriangle size={20} className="text-[#eab308]" />
          <h2 className="font-display text-xl font-bold">Peringatan Stok Minimum</h2>
          <span className="text-xs px-2.5 py-1 rounded-full bg-[#eab308]/15 text-[#eab308] font-medium">{lowStock.length} barang</span>
        </div>
        {lowStock.length === 0 ? (
          <p className="text-sm text-[#8b93a1]">Semua stok masih di atas batas minimum. Tidak ada yang perlu direstock.</p>
        ) : (
          <div className="space-y-2">
            {lowStock.map((p) => (
              <div key={p.id} className="flex flex-wrap items-center justify-between gap-3 p-3 rounded-lg bg-[#0b0f17] border border-[#1a222e]">
                <div><div className="font-medium text-sm">{p.name}</div><div className="label-mono text-[10px]">{p.sku} · {p.location}</div></div>
                <div className="font-mono text-sm"><span className="text-[#eab308] font-semibold">{p.stock}</span> / min {p.min} {p.unit} <span className="text-[#6b7688] block text-[10px]">Saran pesan {Math.max(p.min - p.stock + Math.ceil(p.min * 0.2), p.min)} {p.unit}</span></div>
                <div className="text-xs text-[#8b93a1]">Supplier<div className="text-[#c7d0dc]">{p.supplier}</div></div>
                <button onClick={() => navigate('/po')} className="btn-primary inline-flex items-center gap-1.5 text-xs font-semibold px-3 py-2 rounded-lg"><ClipboardList size={13} /> Buat PO</button>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="card-surface p-6">
        <h2 className="font-display text-xl font-bold mb-4">Sisa Stok per Barang (A → Z)</h2>
        <div className="relative mb-4 max-w-md">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#6b7688]" />
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Cari nama barang atau SKU..." className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg pl-9 pr-3 py-2.5 text-sm outline-none focus:border-[#2563eb]" />
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm tbl">
            <thead><tr className="text-left border-b border-[#1a222e]">{['Nama Barang', 'SKU', 'Kategori', 'Sisa Stok', 'Rusak', 'Nilai Stok', 'Lokasi'].map((h) => <th key={h} className="py-2.5 pr-4 font-semibold">{h}</th>)}</tr></thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr><td colSpan={7} className="py-8 text-center text-[#6b7688]">Belum ada produk terdaftar. Tambah produk atau import data SKU.</td></tr>
              ) : filtered.map((p) => (
                <tr key={p.id} className="tbl-row border-b border-[#131a24]">
                  <td className="py-3 pr-4 font-medium">{p.name}</td>
                  <td className="py-3 pr-4 font-mono text-xs text-[#8b93a1]">{p.sku}</td>
                  <td className="py-3 pr-4"><span className="text-xs px-2 py-0.5 rounded-full" style={{ background: `${catColor(p.category)}1f`, color: catColor(p.category) }}>{p.category}</span></td>
                  <td className="py-3 pr-4 font-mono">{formatNum(p.stock)} {p.unit}</td>
                  <td className="py-3 pr-4 font-mono">{p.damaged || 0}</td>
                  <td className="py-3 pr-4 font-mono">{formatRp(p.stock * p.cost)}</td>
                  <td className="py-3 pr-4 text-[#8b93a1]">{p.location}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="card-surface p-6 lg:col-span-2">
          <h2 className="font-display text-lg font-bold mb-6">Perputaran 7 Hari Terakhir</h2>
          <div className="flex items-end justify-between gap-3 h-52">
            {chart.map((c) => (
              <div key={c.key} className="flex-1 flex flex-col items-center gap-2 h-full justify-end">
                <div className="w-full rounded-t-md bar" style={{ height: `${(c.vol / maxVol) * 100}%`, minHeight: c.vol > 0 ? '4px' : '0', background: 'linear-gradient(180deg,#3b82f6,#1d4ed8)' }} />
                <div className="label-mono text-[9px]">{c.key}</div>
              </div>
            ))}
          </div>
        </div>
        <div className="card-surface p-6">
          <h2 className="font-display text-lg font-bold mb-4">Stok per Kategori</h2>
          {byCat.length === 0 ? <p className="text-sm text-[#8b93a1]">Belum ada produk terdaftar.</p> : (
            <div className="space-y-3">
              {byCat.map((c) => (
                <div key={c.name}>
                  <div className="flex justify-between text-xs mb-1"><span>{c.name}</span><span className="font-mono text-[#8b93a1]">{formatRpShort(c.val)}</span></div>
                  <div className="h-2 rounded-full bg-[#0b0f17] overflow-hidden"><div className="h-full rounded-full" style={{ width: `${(c.val / totCat) * 100}%`, background: c.color }} /></div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="card-surface p-6">
        <h2 className="font-display text-lg font-bold mb-4">Aktivitas Terakhir</h2>
        <div className="space-y-2">
          {transactions.slice(0, 8).map((t) => (
            <div key={t.id} className="flex items-center justify-between gap-3 p-3 rounded-lg bg-[#0b0f17] border border-[#151d28]">
              <div><div className="font-medium text-sm">{t.product}</div><div className="label-mono text-[10px]">{t.sku} · {formatDate(t.time)}</div></div>
              <div className={`flex items-center gap-2 text-sm font-mono ${t.type === 'MASUK' ? 'text-[#22c55e]' : 'text-[#ef4444]'}`}>
                {t.type === 'MASUK' ? <ArrowDownRight size={15} /> : <ArrowUpRight size={15} />}
                <span className="text-xs px-2 py-0.5 rounded-full" style={{ background: t.type === 'MASUK' ? 'rgba(34,197,94,.15)' : 'rgba(239,68,68,.15)' }}>{t.type}</span>
                <span className="font-semibold">{t.change > 0 ? '+' : ''}{t.change}</span>
              </div>
            </div>
          ))}
          {transactions.length === 0 && <p className="text-sm text-[#8b93a1]">Belum ada aktivitas.</p>}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { UploadCloud, FileSpreadsheet, Download, CheckCircle2 } from 'lucide-react';
import { useData } from '../context/DataContext';
import { apiError } from '../lib/api';
import { toast } from 'sonner';

const TEMPLATE = 'sku;nama;jumlah;kategori;satuan;harga_beli;harga_jual;supplier;lokasi\nB0010001X;CONTOH BERAS MEDIUM 5 KG;100;Beras;Kg;0;0;Nama Supplier;Gudang I\n';

const ImportData = () => {
  const { importCsv } = useData();
  const [file, setFile] = useState(null);
  const [busy, setBusy] = useState(false);

  const process = async () => {
    if (!file) { toast.error('Pilih file terlebih dahulu'); return; }
    setBusy(true);
    try {
      const res = await importCsv(file);
      toast.success(`Import berhasil — ${res.inserted} SKU baru, ${res.updated} SKU diperbarui`);
      setFile(null);
    } catch (e) { toast.error(apiError(e)); }
    setBusy(false);
  };

  const downloadTemplate = () => {
    const blob = new Blob([TEMPLATE], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'template_import_sku.csv'; a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6" data-testid="import-page">
      <div>
        <div className="label-mono mb-2">Master Data</div>
        <h1 className="font-display text-4xl font-bold">Import Data SKU</h1>
        <p className="text-[#8b93a1] mt-2 max-w-2xl">Unggah file CSV untuk menambahkan banyak produk sekaligus. SKU yang sudah ada akan diperbarui datanya. Gunakan template resmi agar kolom terbaca dengan benar.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="card-surface p-6 lg:col-span-2">
          <label className="block border-2 border-dashed border-[#242f3d] rounded-2xl p-12 text-center cursor-pointer hover:border-[#2563eb] transition-colors">
            <input data-testid="import-file-input" type="file" accept=".csv" className="hidden" onChange={(e) => setFile(e.target.files[0])} />
            <UploadCloud size={44} className="mx-auto mb-4 text-[#60a5fa]" />
            <div className="font-display font-bold text-lg">{file ? file.name : 'Tarik & lepas file di sini'}</div>
            <div className="text-sm text-[#8b93a1] mt-1">atau klik untuk memilih file (.csv — maks 5MB)</div>
          </label>
          <button data-testid="import-process-btn" onClick={process} disabled={busy} className="btn-primary w-full mt-4 flex items-center justify-center gap-2 py-3 rounded-lg font-semibold text-sm disabled:opacity-60"><FileSpreadsheet size={16} /> {busy ? 'Memproses...' : 'Proses Import'}</button>
        </div>

        <div className="card-surface p-6">
          <h2 className="font-display text-lg font-bold mb-4">Panduan</h2>
          <ul className="space-y-3 text-sm text-[#aab4c4]">
            {['Pemisah kolom menggunakan titik koma (;)', 'Kolom wajib: sku, nama, jumlah, kategori, satuan', 'SKU yang sama akan diperbarui, bukan digandakan', 'Supplier baru otomatis ditambahkan'].map((t) => (
              <li key={t} className="flex items-start gap-2"><CheckCircle2 size={16} className="text-[#22c55e] mt-0.5 shrink-0" /> {t}</li>
            ))}
          </ul>
          <button data-testid="download-template-btn" onClick={downloadTemplate} className="w-full mt-5 inline-flex items-center justify-center gap-2 text-sm font-medium px-4 py-2.5 rounded-lg border border-[#242f3d] hover:bg-[#141a24]"><Download size={15} /> Unduh Template CSV</button>
        </div>
      </div>
    </div>
  );
};

export default ImportData;

